"""Offline display of recorded launcher controls, not a new physics run."""
import pathlib,json,csv,hashlib,argparse
H=pathlib.Path(__file__).resolve().parent

def build(run_dir,out):
 run_dir=pathlib.Path(run_dir);out=pathlib.Path(out)
 if out.exists():raise ValueError('Fresh replay output required')
 report=json.loads((run_dir/'report.json').read_text());g=json.loads((H/'current-geometry.json').read_text());cases=[]
 if hashlib.sha256((H/'current-geometry.json').read_bytes()).hexdigest()!=report['inputs']['current-geometry.json']:raise ValueError('Geometry/report binding')
 for case in report['cases']:
  if case['name'] not in ['nominal','faster handoff']:continue
  p=run_dir/case['trace']['file']
  if hashlib.sha256(p.read_bytes()).hexdigest()!=case['trace']['sha256']:raise ValueError('Trace hash')
  with p.open() as f:rows=list(csv.DictReader(f))
  for row in rows:
   for k in row:
    if k!='phase':row[k]=float(row[k])
  cases.append({'name':case['name'],'outcome':case['plant']['outcome'],'rows':rows})
 payload={'cases':cases,'geometry':g,'runId':report['runId'],'reportSha256':hashlib.sha256((run_dir/'report.json').read_bytes()).hexdigest()}
 html='''<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>2024 launcher control replay</title><style>body{background:#102435;color:#edf6fc;font:16px system-ui;margin:0}main{max-width:1000px;margin:auto;padding:20px}p{line-height:1.5;color:#c2d6e4}.warn{background:#503b20;padding:14px;border-radius:10px}canvas{background:#e9f1f5;width:100%;border-radius:12px}select,button{font:inherit;padding:10px;margin:8px}input{width:100%}small{overflow-wrap:anywhere}#stats{font-size:20px;margin:14px 0}</style><main><h1>2024 component-launcher replay</h1><p class="warn">This is a launcher-only control: upstream pinch-belt drive is deliberately missing. The 1.5 m/s handoff reverses. The 2 m/s case is a sensitivity test, NOT a proposed fix or a successful robot cycle.</p><p>Current nominal 48.26 mm tread radius and shifted shooter mount. Recorded simulated state, fixed guide-aligned NOTE attitude. Side projection below is schematic, not whole-robot CAD or collision certification.</p><select id="case" aria-label="Control scenario"></select><button id="play">Play</button><input id="time" aria-label="Replay time" type="range" min="0" step="any"><div id="stats"></div><canvas id="view" width="960" height="540"></canvas><p id="outcome"></p><small id="binding"></small><p>Blue: opposed launcher tread cross-sections. Orange capsule: NOTE center/attitude marker (not collision outline). Dashed line: guide direction. Feed entry energy, normal force, friction and inertia are hypotheses. Whole-field structures, piece deformation/spin and calibrated traction are absent. No score or physical acceptance.</p></main><script>const data=__DATA__,sel=document.querySelector('#case'),slider=document.querySelector('#time'),ctx=document.querySelector('#view').getContext('2d');data.cases.forEach((c,i)=>{let o=document.createElement('option');o.value=i;o.textContent=c.name==='nominal'?'1.5 m/s coast-only control':'2.0 m/s prescribed-speed sensitivity';sel.appendChild(o)});let playing=false,last=0;const g=data.geometry,s=g.shooter,a=s.releasePitchDeg*Math.PI/180,p=s.pivot;function point(u,z=0){return[p[0]+u*Math.cos(a)-z*Math.sin(a),p[2]+u*Math.sin(a)+z*Math.cos(a)]}function xy(q){return[100+q[0]*1000,500-q[1]*460]}function line(q,r,color,width=3){q=xy(q);r=xy(r);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(...q);ctx.lineTo(...r);ctx.stroke()}function draw(){let c=data.cases[Number(sel.value)],t=Number(slider.value),r=c.rows[0];for(let q of c.rows){if(q.timeS>t)break;r=q}ctx.clearRect(0,0,960,540);ctx.lineCap='round';ctx.setLineDash([7,7]);line(point(-.08),point(.5),'#95a9b6');ctx.setLineDash([]);const radius=g.wheelRadiusMm/1000,half=s.nominalGap/2+radius;for(let z of[-half,half]){let q=xy(point(g.wheelStationMm/1000,z));ctx.fillStyle='#2875a5';ctx.beginPath();ctx.ellipse(q[0],q[1],radius*1000,radius*460,0,0,2*Math.PI);ctx.fill()}if(r.phase==='feed'){let u=g.wheelStationMm/1000+r.noteXFromStationM;line(point(u-.1524),point(u+.1524),'#e47727',24)}ctx.fillStyle='#102435';ctx.font='18px system-ui';ctx.fillText('Robot-local side projection',24,32);document.querySelector('#stats').textContent=t.toFixed(3)+' s | '+r.phase+' | NOTE '+r.pieceSpeedMps.toFixed(2)+' m/s | '+r.minRpm.toFixed(0)+' RPM | bus '+r.busV.toFixed(2)+' V';document.querySelector('#outcome').textContent='Recorded outcome: '+c.outcome;document.querySelector('#binding').textContent='Run '+data.runId+' | report SHA-256 '+data.reportSha256}function reset(){playing=false;slider.max=data.cases[Number(sel.value)].rows.at(-1).timeS;slider.value=0;document.querySelector('#play').textContent='Play';draw()}sel.onchange=reset;slider.oninput=draw;document.querySelector('#play').onclick=()=>{if(Number(slider.value)>=Number(slider.max))slider.value=0;playing=!playing;last=0;document.querySelector('#play').textContent=playing?'Pause':'Play'};function tick(n){if(playing&&last){slider.value=Math.min(Number(slider.max),Number(slider.value)+(n-last)/1000*.2);draw();if(Number(slider.value)>=Number(slider.max)){playing=false;document.querySelector('#play').textContent='Play'}}last=n;requestAnimationFrame(tick)}reset();requestAnimationFrame(tick);</script>'''
 out.write_bytes(html.replace('__DATA__',json.dumps(payload,allow_nan=False).replace('</','<\\/')).encode())
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--run',required=True,type=pathlib.Path);p.add_argument('--output',required=True,type=pathlib.Path);a=p.parse_args();build(a.run,a.output)
